/* Parameter studies use the scientific workbench's neutral industrial palette. */
.parameter-study-workbench{min-width:0}
.parameter-study-workbench h2{font-size:17px}
.parameter-study-workbench .section-header h2{margin:0 0 5px}
.parameter-study-workbench .section-header p{font-size:12px;color:var(--muted)}
.parameter-study-selected{background:#eef1f3}
.parameter-study-summary{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;margin-bottom:16px}
.parameter-study-summary p{font-size:13px;margin-top:10px}
.parameter-study-summary progress{width:min(360px,100%);height:16px;accent-color:#4b555e}
.parameter-study-provenance{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 22px;padding:14px 0;margin:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.parameter-study-provenance div{min-width:0}
.parameter-study-provenance dt{font-size:11px;color:var(--muted);margin-bottom:5px}
.parameter-study-provenance dd{font-size:12px;overflow-wrap:anywhere;margin:0}
.parameter-study-filter{min-width:210px;font-size:12px}
.parameter-study-filter input{margin-top:5px}
.parameter-study-pager{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap;padding:12px 16px;border-top:1px solid var(--line);font-size:12px}
.parameter-study-pager>span{margin-right:auto;color:var(--muted)}
.parameter-study-pager button{padding:6px 10px;font-size:12px}
.parameter-study-workbench .technical .definition{max-width:460px}
.parameter-study-workbench .row-detail{max-width:400px}
.parameter-study-workbench .row-detail dd{font-variant-numeric:tabular-nums}
.parameter-study-workbench [data-parameter-study-results]>.note{margin-bottom:16px}
.parameter-study-workbench [data-parameter-study-results] .filters{margin-top:18px}
.parameter-study-workbench .file-list{margin-top:20px;border-top:1px solid var(--line)}
.parameter-study-axis-heading{display:flex;gap:14px;align-items:flex-end;margin-bottom:16px}
.parameter-study-axis-heading>label{flex:1}
.parameter-study-axis-heading>button{flex:0 0 auto;margin-bottom:1px;font-size:12px}
.parameter-study-axis select[multiple]{min-height:154px;padding:4px}
